 config=next(ast.literal_eval(n.value) for n in t.body if isinstance(n,ast.Assign) and any(isinstance(a,ast.Name) and a.id=='CONFIG' for a in n.targets))
 assert config==v['config']
 assert set(config)==set(base_config)
 changed={k for k in config if config[k]"'!=base_config[k]}
 assert changed<={'"'tower_hidden_units','residual_hidden'}
 init=next(m for c in t.body if isinstance(c,ast.ClassDef) and c.name=='Model' for m in c.body if isinstance(m,ast.FunctionDef) and m.name=='__init__')
 defaults={a.arg:ast.literal_eval(d) for a,d in zip(init.args.args[-len(init.args.defaults):],init.args.defaults)}
 for k,val in config.items():
